def run(spec: str, verilog: str, ports: list[dict]) -> dict:
    """
    Returns {'fired': True, 'findings': [msg]} if the design has any output
    that is driven only by a continuous assignment (assign) and never appears
    in the left-hand side of an always block (including always_ff, always @(posedge clk),
    always @*, etc.). Otherwise returns {'fired': False, 'findings': []}.
    """
    import re

    # Find output port names
    output_ports = {p['name'] for p in ports if p.get('direction') == 'output'}

    # Normalize whitespace and remove comments for easier parsing
    def strip_comments(text):
        # remove // comments
        text = re.sub(r'//.*', '', text)
        # remove /* */ comments
        return re.sub(r'/\\*.*?\\*/', '', text, flags=re.DOTALL)

    v = strip_comments(verilog)

    # Find all always blocks (including always_ff, always @(...), always @*)
    always_blocks = re.findall(r'always\s*@*\s*\([^)]*\)\s*begin[\s\S]*?end', v, re.IGNORECASE)
    # Also capture always @* without explicit begin/end? We'll approximate with a simpler pattern:
    always_any = re.findall(r'always\s*@*\s*[^;]*;', v, re.IGNORECASE)
    always_blocks.extend(always_any)

    # Collect LHS signals inside always blocks
    lhs_in_always = set()
    for block in always_blocks:
        # Find assignments like signal <= expr or signal = expr inside the block
        # Look for patterns: <identifier> (<=|=) 
        assignments = re.findall(r'([a-zA-Z_][a-zA-Z0-9_]*)\s*(<=|=)', block)
        for lhs, _ in assignments:
            lhs_in_always.add(lhs)

    # Find continuous assignments: assign <lhs> = <expr>;
    assign_matches = re.findall(r'assign\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*=', v, re.IGNORECASE)
    assigned_in_assign = set(assign_matches)

    # Determine outputs that are only assigned via assign and never in always
    problematic = []
    for out in output_ports:
        if out in assigned_in_assign and out not in lhs_in_always:
            problematic.append(out)

    if problematic:
        findings = [f"Output(s) {', '.join(problematic)} driven only by combinational assign with no clocked always block."]
        return {"fired": True, "findings": findings}
    else:
        return {"fired": False, "findings": []}
}
